def snakeMoves(grid):
    n = len(grid)
    seen = [[[False, False] for _ in range(n)] for _ in range(n)]
    seen[0][0][0] = True
    frontier = [(0, 0, 0)]
    steps = 0
    while frontier:
        nxt = []
        for r, c, o in frontier:
            if r == n - 1 and c == n - 2 and o == 0:
                return steps
            cand = []
            if o == 0:
                if c + 2 < n and grid[r][c + 2] == 0:
                    cand.append((r, c + 1, 0))
                if r + 1 < n and grid[r + 1][c] == 0 and grid[r + 1][c + 1] == 0:
                    cand.append((r + 1, c, 0))
                    cand.append((r, c, 1))
            else:
                if r + 2 < n and grid[r + 2][c] == 0:
                    cand.append((r + 1, c, 1))
                if c + 1 < n and grid[r][c + 1] == 0 and grid[r + 1][c + 1] == 0:
                    cand.append((r, c + 1, 1))
                    cand.append((r, c, 0))
            for nr, nc, no in cand:
                if not seen[nr][nc][no]:
                    seen[nr][nc][no] = True
                    nxt.append((nr, nc, no))
        frontier = nxt
        steps += 1
    return -1
